import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
export async function exerciseCollageTen(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,dialog=()=>page.getByRole('dialog',{name:t('照片拼图','Photo collage'),exact:true}),b=(zh,en)=>dialog().getByRole('button',{name:t(zh,en),exact:true}),label=(zh,en)=>dialog().getByLabel(t(zh,en),{exact:true}),tool=()=>page.locator('.studio-tool').filter({hasText:t('照片拼图','Photo collage')});
 const bytes=await page.evaluate(async()=>{const c=new OffscreenCanvas(80,60),x=c.getContext('2d');x.fillStyle='#bb5533';x.fillRect(0,0,80,60);return [...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())];}),files=['A.png','B.png','C.png'].map(name=>({name,mimeType:'image/png',buffer:Buffer.from(bytes)}));
 await dialog().locator('input[type=file]').first().setInputFiles(files.slice(0,2));await expect(label('画布宽度','Canvas width')).toBeVisible();for(const [zh,en,value] of [['画布宽度','Canvas width','640'],['画布高度','Canvas height','480']]){await label(zh,en).fill(value);await label(zh,en).press('Tab');}await b('设为新拼图默认画布','Use as default canvas').click();await label('显示未填满提示','Show gap guides').uncheck();await label('拼图输出格式','Collage output format').selectOption('webp');await label('WebP 质量','WebP quality').fill('77');
 const download=page.waitForEvent('download');await b('导出拼图 WebP','Export collage WebP').click();const exported=await download,webp=readFileSync(await exported.path());expect(exported.suggestedFilename()).toMatch(/\.webp$/);expect(webp.subarray(0,4).toString()).toBe('RIFF');expect(webp.subarray(8,12).toString()).toBe('WEBP');
 await label('格内缩放','Cell zoom').fill('1.6');const cell=()=>dialog().getByRole('button',{name:t('拼图单元格 1','Collage cell 1'),exact:true});await cell().focus();await cell().press('Shift+F10');const menu=()=>page.getByRole('menu',{name:t('照片格菜单','Photo cell menu')});await expect(menu()).toBeVisible();await menu().getByRole('menuitem',{name:t('重置取景','Reset framing'),exact:true}).click();await expect(label('格内缩放','Cell zoom')).toHaveValue('1');await cell().click({button:'right'});await menu().getByRole('menuitem',{name:t('移除照片','Remove photo'),exact:true}).click();await expect(dialog().locator('.collage-cells>button')).toHaveCount(1);
 await cell().click({button:'right'});await expect(menu().getByRole('menuitem',{name:t('移除照片','Remove photo'),exact:true})).toBeDisabled();const choose=page.waitForEvent('filechooser');await menu().getByRole('menuitem',{name:t('替换照片','Replace photo'),exact:true}).click();await(await choose).setFiles({...files[0],name:'Replacement.png'});await expect(dialog().locator('.collage-controls')).toContainText('Replacement.png');
 const stage=dialog().getByLabel(t('拼图画布','Collage canvas'),{exact:true});await stage.evaluate(e=>e.scrollIntoView({block:'center'}));await stage.click({position:{x:2,y:2}});await expect(cell()).toHaveAttribute('aria-pressed','false');await expect(label('格内缩放','Cell zoom')).toHaveCount(0);await cell().focus();await cell().press('Escape');await expect(dialog()).toBeVisible();await expect(cell()).toHaveAttribute('aria-pressed','false');await cell().click();
 await label('工程名称','Project name').fill('Alpha_%');await b('保存到图库','Save to library').click();await expect(b('另存拼图工程','Save project copy')).toBeEnabled();await label('工程名称','Project name').fill('Alpha_% renamed');page.once('dialog',d=>d.dismiss());await b('关闭','Close').click();await expect(dialog()).toBeVisible();await b('保存到图库','Save to library').click();await expect(dialog().locator('.collage-projects')).toContainText('Alpha_% renamed');await b('关闭','Close').click();
 await tool().click();await dialog().locator('input[type=file]').first().setInputFiles(files[0]);await expect(label('画布宽度','Canvas width')).toHaveValue('640');await expect(label('画布高度','Canvas height')).toHaveValue('480');await expect(label('拼图输出格式','Collage output format')).toHaveValue('webp');await expect(label('WebP 质量','WebP quality')).toHaveValue('77');await expect(label('显示未填满提示','Show gap guides')).not.toBeChecked();await b('恢复默认画布偏好','Restore default canvas preference').click();await expect(label('画布宽度','Canvas width')).toHaveValue('640');
 await b('图库内拼图工程','Library collage projects').click();await label('搜索拼图工程','Search collage projects').fill('ALPHA_%');await b('搜索工程','Search projects').click();await expect(dialog().locator('.collage-project-list>li')).toHaveCount(1);await label('工程排序','Project sort').selectOption('name');await label('工程排序方向','Project sort direction').selectOption('asc');await b('查看来源','View sources').click();await expect(dialog().getByLabel(t('工程来源信息','Project source information'))).toContainText('Replacement.png');await expect(dialog().getByLabel(t('工程来源信息','Project source information'))).toContainText('SHA-256');await dialog().evaluate(e=>e.scrollTop=0);await dialog().screenshot({path:info.outputPath('collage-ten-'+lang+'.png')});expect(await dialog().evaluate(e=>e.scrollWidth<=e.clientWidth+1)).toBe(true);if(lang==='en')expect(await dialog().innerText()).not.toMatch(/[\u3400-\u9fff]/);
 page.once('dialog',d=>d.accept());await b('打开工程','Open project').click();await expect(label('画布宽度','Canvas width')).toHaveValue('640');await b('关闭','Close').click();await tool().click();await b('批量拼图','Batch collage').click();
 const batch=()=>page.getByRole('dialog',{name:t('批量拼图','Batch collage'),exact:true}),bb=(zh,en)=>batch().getByRole('button',{name:t(zh,en),exact:true}),bl=(zh,en)=>batch().getByLabel(t(zh,en),{exact:true});await batch().locator('input[type=file]').first().setInputFiles(files);await expect(bl('每组照片数','Photos per group')).toBeVisible();await bl('每组照片数','Photos per group').selectOption('2');await bl('分组顺序','Group order').selectOption('filename');await bl('余图处理','Remainder handling').selectOption('drop');await bl('批量输出格式','Batch output format').selectOption('webp');await bl('WebP 质量','WebP quality').fill('65');await bl('工程名称','Project name').fill('Saved batch defaults');await bb('保存到图库','Save to library').click();await expect(bb('另存拼图工程','Save project copy')).toBeEnabled();await bb('开始逐页导出','Export pages').click();await expect(bb('下载已完成页 ZIP','Download completed pages ZIP')).toBeEnabled();const zipDownload=page.waitForEvent('download');await bb('下载已完成页 ZIP','Download completed pages ZIP').click();const zip=readFileSync(await(await zipDownload).path());expect(zip.readUInt32LE(0)).toBe(0x04034b50);const size=zip.readUInt16LE(26),extra=zip.readUInt16LE(28);expect(zip.subarray(30,30+size).toString()).toMatch(/\.webp$/);expect(zip.subarray(30+size+extra+8,30+size+extra+12).toString()).toBe('WEBP');await bb('关闭','Close').click();
 await tool().click();await b('批量拼图','Batch collage').click();await batch().locator('input[type=file]').first().setInputFiles(files);await expect(bl('每组照片数','Photos per group')).toHaveValue('2');await expect(bl('分组顺序','Group order')).toHaveValue('filename');await expect(bl('余图处理','Remainder handling')).toHaveValue('drop');await expect(bl('批量输出格式','Batch output format')).toHaveValue('webp');await expect(bl('WebP 质量','WebP quality')).toHaveValue('65');await bl('每组照片数','Photos per group').selectOption('3');await bb('图库内拼图工程','Library collage projects').click();await bl('搜索拼图工程','Search collage projects').fill('Saved batch');await bb('搜索工程','Search projects').click();await expect(batch().locator('.collage-project-list>li')).toHaveCount(1);page.once('dialog',d=>d.accept());await batch().locator('.collage-project-list>li').filter({hasText:'Saved batch defaults'}).getByRole('button',{name:t('打开工程','Open project'),exact:true}).click();await expect(bl('每组照片数','Photos per group')).toHaveValue('2');await bb('图库内拼图工程','Library collage projects').click();const row=batch().locator('.collage-project-list>li').filter({hasText:'Saved batch defaults'});await row.getByRole('button',{name:t('查看来源','View sources'),exact:true}).click();await expect(row).toContainText(t('当前跳过','Currently skipped'));for(let i=0;i<2;i++){page.once('dialog',d=>d.accept());await batch().locator('.collage-project-list>li').first().getByRole('button',{name:t('删除工程','Delete project'),exact:true}).click();await expect(batch().locator('.collage-project-list>li')).toHaveCount(1-i);}page.once('dialog',d=>d.accept());await bb('关闭','Close').click();
}
